from .schema import B, concept as C, step as S, example as E, lab as P, quiz as Q, lesson as L
LESSONS = [
L('OS-W01',B('Windows: contexto, herramientas y arquitectura','Windows: context, tools and architecture'),B('¿Windows Terminal, PowerShell y Windows son lo mismo?','Are Windows Terminal, PowerShell and Windows the same thing?'),B('Identificar edición, motor, cuenta y objeto administrado antes de actuar.','Identify edition, engine, account and managed object before acting.'),[
 C(B('Tres nombres, tres capas','Three names, three layers'),B('Windows Terminal es una aplicación de terminal que puede alojar distintos intérpretes. cmd.exe procesa comandos y lotes; PowerShell trabaja con su lenguaje y cmdlets. Windows proporciona APIs, procesos, servicios, seguridad y controladores. Una ventana puede ejecutar otra cuenta o incluso una sesión remota. El título de la ventana y el directorio no prueban por sí solos la identidad efectiva.','Windows Terminal is a terminal application that can host different interpreters. cmd.exe handles commands and batch files; PowerShell supplies its language and cmdlets. Windows provides APIs, processes, services, security and drivers. A window may run another account or a remote session. Window title and directory alone do not prove effective identity.'),B('Terminal ≠ intérprete ≠ sistema.','Terminal ≠ interpreter ≠ operating system.')),
 C(B('GUI administrativa y APIs','Administrative GUI and APIs'),B('Administrador de tareas, Servicios, Visor de eventos y Administración de equipos son vistas de objetos de Windows. Un proceso tiene identidad, memoria y recursos; un servicio añade un contrato con el Service Control Manager. El Registro organiza configuración en claves y valores de ámbitos distintos. No debe usarse como almacén de contraseñas ni exportarse íntegro para una práctica sencilla.','Task Manager, Services, Event Viewer and Computer Management are views of Windows objects. A process has identity, memory and resources; a service adds a contract with Service Control Manager. The Registry organizes configuration into keys and values with different scopes. Do not use it as a password store or export the whole Registry for a small lab.'),B('Cada consola administra objetos concretos.','Each console manages specific objects.')),
 C(B('Versión, edición y privilegios','Version, edition and privilege'),B('Cliente y servidor, compilación, arquitectura y módulos determinan las funciones disponibles. Windows PowerShell 5.1 y PowerShell 7 pueden coexistir. Tener PowerShell en Linux no proporciona las APIs nativas de Windows. UAC y elevación afectan al token del proceso; modificar USERNAME o USERPROFILE no cambia de identidad. Utiliza cuenta estándar y eleva solo la operación que lo necesita.','Client/server edition, build, architecture and modules determine available features. Windows PowerShell 5.1 and PowerShell 7 can coexist. PowerShell on Linux does not provide native Windows APIs. UAC and elevation affect the process token; modifying USERNAME or USERPROFILE does not change identity. Use a standard account and elevate only operations needing it.'),B('Comprueba disponibilidad; no fuerces equivalencias.','Check availability; do not force equivalence.'))],
 [B('Terminal','Terminal'),B('cmd.exe / PowerShell','cmd.exe / PowerShell'),B('APIs y objetos Windows','Windows APIs and objects'),B('Token, kernel y dispositivos','Token, kernel and devices')],
 E(B('Ficha mínima de Windows','Minimal Windows record'),'PowerShell',"$PSVersionTable | Select-Object PSVersion, PSEdition\n[Environment]::Is64BitProcess\nwhoami.exe\nGet-ComputerInfo -Property WindowsProductName,OsVersion,OsArchitecture",B('Versión del motor, arquitectura del proceso, identidad y versión del SO por separado.','Engine version, process architecture, identity and OS version separately.'),B('Select-Object sobre PSVersionTable puede no mostrar los datos como esperas al ser una tabla hash: consulta también $PSVersionTable.PSVersion. La inspección del tipo forma parte del ejercicio.','Select-Object on the PSVersionTable hashtable may not display data as expected: also inspect $PSVersionTable.PSVersion. Type inspection is part of the exercise.')),
 P(B('Windows nativo o VM con GUI; cuenta estándar; sin datos personales en capturas.','Native Windows or GUI VM; standard account; no personal data in screenshots.'),[
 S(B('Abre Terminal, selecciona PowerShell y ejecuta las consultas.','Open Terminal, choose PowerShell and run the queries.'),B('No confundes arquitectura de proceso y de SO.','Do not confuse process and OS architecture.')),
 S(B('Contrasta edición y versión mediante Configuración y winver.','Compare edition and version through Settings and winver.'),B('Los valores describen productos/capas diferentes, no necesariamente un conflicto.','Values describe different products/layers, not necessarily a conflict.'),'winver'),
 S(B('Abre Bloc de notas y localiza su proceso en GUI y CLI.','Open Notepad and find its process in GUI and CLI.'),B('PID, nombre y cuenta se anotan con el instante de observación.','Record PID, name and account with observation time.'),'Get-Process -Name notepad -ErrorAction SilentlyContinue'),
 S(B('Cierra normalmente solo el Bloc de notas del ejercicio.','Normally close only the exercise Notepad window.'),B('Comprueba que termina el proceso correspondiente sin matar procesos ajenos.','Check that the corresponding process ends without killing unrelated processes.'))],B('Ficha de entorno y mapa GUI/CLI.','Environment record and GUI/CLI map.'),B('Sitúas shell, proceso, servicio y SO sin privilegios innecesarios.','Locate shell, process, service and OS without unnecessary privilege.'),B('Cierra consolas y documentos ficticios. No cambies políticas ni Registro.','Close consoles and fictitious documents. Do not change policies or Registry.'),B('Un cmdlet no está disponible en ese motor.','A cmdlet is unavailable in that engine.'),B('Consulta Get-Command y documentación de módulo/edición; no desactives controles ni supongas que falta el objeto.','Check Get-Command and module/edition documentation; do not disable controls or assume the object is absent.')),
 Q(B('¿Cambiar USERPROFILE cambia el token del proceso?','Does changing USERPROFILE change the process token?'),[B('No.','No.'),B('Sí.','Yes.'),B('Solo dentro de Terminal.','Only in Terminal.')],0,B('Las variables de entorno no sustituyen autenticación o elevación.','Environment variables do not replace authentication or elevation.')),B('Dar por disponible en PowerShell 7 cualquier cmdlet antiguo.','Assuming every legacy cmdlet exists in PowerShell 7.'),B('Antes del comando: versión, módulo, identidad y alcance.','Before the command: version, module, identity and scope.'),['ms-process','powershell'],['M13','M14']),
L('OS-W02',B('Archivos, usuarios, ACL y perfiles','Files, users, ACLs and profiles'),B('¿Qué permiso permite leer pero no cambiar la autorización?','Which permission allows reading but not changing authorization?'),B('Diseñar acceso NTFS mínimo y distinguir cuenta de perfil.','Design minimal NTFS access and distinguish account from profile.'),[
 C(B('Identidad y token','Identity and token'),B('Windows identifica sujetos mediante SID. El token contiene grupos y privilegios que intervienen en la decisión de acceso. Un nombre puede cambiar sin cambiar el SID; una cuenta recreada con el mismo nombre no es necesariamente la misma identidad. Las pertenencias deben verificarse en la sesión efectiva, especialmente después de un cambio de rol.','Windows identifies subjects using SIDs. The token contains groups and privileges affecting access decisions. A name can change while the SID stays; an account recreated with the same name is not necessarily the same identity. Verify memberships in the effective session, especially after a role change.'),B('El nombre visible no es toda la identidad.','The displayed name is not the whole identity.')),
 C(B('Permisos efectivos y herencia','Effective permissions and inheritance'),B('Una ACL contiene entradas de acceso; grupos, herencia, permisos explícitos y privilegios contribuyen al resultado. No reduzcas la evaluación a la regla simplista de que deny siempre gana. Para recursos compartidos intervienen además permisos del share. Leer, modificar datos y administrar la ACL son operaciones distintas. Registra el estado original y prueba con la identidad de destino, no solo como administrador.','An ACL contains access entries; groups, inheritance, explicit permissions and privileges contribute to the result. Do not reduce evaluation to the simplistic rule that deny always wins. Shares add another permission layer. Reading, modifying data and administering the ACL differ. Record original state and test as the target identity, not only as administrator.'),B('Sujeto + objeto + acción + contexto.','Subject + object + action + context.')),
 C(B('Perfil y datos del usuario','User profile and data'),B('El perfil mantiene preferencias, datos y cachés; la cuenta mantiene identidad. Los perfiles locales, temporales, itinerantes, obligatorios o de contenedor tienen condiciones diferentes. Borrar un perfil no revoca sesiones ni permisos en otras aplicaciones. En un equipo compartido verifica que el siguiente alumno no hereda datos o sesiones. No resuelvas un perfil temporal renombrando carpetas del sistema sin un procedimiento de recuperación.','A profile maintains preferences, data and caches; an account maintains identity. Local, temporary, roaming, mandatory and containerized profiles have different conditions. Deleting a profile does not revoke sessions or permissions in other applications. On shared devices, verify the next learner inherits neither data nor sessions. Do not fix a temporary profile by renaming system folders without recovery procedures.'),B('Cuenta, perfil y sesión se gestionan por separado.','Manage account, profile and session separately.'))],
 [B('Cuenta y grupos','Account and groups'),B('Token de sesión','Session token'),B('ACL + herencia + share','ACL + inheritance + share'),B('Acceso efectivo','Effective access')],
 E(B('Carpeta nueva con metadatos observables','New folder with observable metadata'),'PowerShell',"$work = Join-Path $env:TEMP ('os-aula-' + [guid]::NewGuid())\nNew-Item -ItemType Directory -Path $work | Out-Null\nSet-Content -LiteralPath (Join-Path $work 'nota.txt') -Value 'dato ficticio'\nGet-Acl -LiteralPath $work | Select-Object Owner,AccessToString\nGet-FileHash -LiteralPath (Join-Path $work 'nota.txt') -Algorithm SHA256",B('Carpeta única, propietario/ACL y hash. La herencia depende de la ubicación.','Unique folder, owner/ACL and hash. Inheritance depends on location.'),B('No se concede permiso nuevo. Esta es la línea base sobre la que el docente aprueba una modificación acotada.','No new permission is granted. This is the baseline for an instructor-approved scoped change.')),
 P(B('VM Windows con NTFS, dos cuentas estándar de aula y administrador docente. No hacerlo sobre documentos personales.','Windows VM with NTFS, two standard classroom accounts and instructor administrator. Do not use personal documents.'),[
 S(B('Crea la carpeta del ejemplo y exporta su ACL a una evidencia local protegida.','Create the example folder and export its ACL to protected local evidence.'),B('Estado original conservado antes de cualquier cambio.','Original state preserved before any change.'),'Get-Acl -LiteralPath $work | Export-Clixml -LiteralPath (Join-Path $env:TEMP "os-aula-acl.xml")'),
 S(B('En Seguridad avanzada de la carpeta, añade únicamente lectura y ejecución a la cuenta lectora aprobada; conserva propietario y recuperación del docente.','In Advanced Security, add only Read and Execute for the approved reader; preserve owner and instructor recovery.'),B('Anota herencia y alcance sobre carpeta/archivos; no apliques la regla a todo TEMP.','Record inheritance and folder/file scope; do not apply to all TEMP.')),
 S(B('Desde la sesión lectora abre nota.txt y prueba guardar un cambio.','From the reader session open nota.txt and attempt to save a change.'),B('Lectura permitida, escritura denegada según el diseño; si permisos previos permiten escribir, corrige el diseño de la carpeta de ensayo.','Read allowed, write denied as designed; if previous permissions permit writing, correct the test folder design.')),
 S(B('Revoca solo la concesión temporal y repite con la sesión/identidad correcta.','Revoke only the temporary grant and repeat under the correct identity/session.'),B('No quedan grupos o ACE temporales sin justificar.','No unjustified temporary groups or ACEs remain.'))],B('ACL, SID ficticios, matriz y resultados permitidos/denegados.','ACL, fictitious SIDs, matrix and allowed/denied results.'),B('Demuestras acceso efectivo sin control total para todos.','Demonstrate effective access without Everyone Full Control.'),B('Restaura ACL aprobada o elimina solo la carpeta única tras conservar evidencia. No borres perfiles reales.','Restore the approved ACL or remove only the unique folder after preserving evidence. Do not delete real profiles.'),B('El lector puede escribir por otra pertenencia de grupo.','The reader can write through another group membership.'),B('Revisa acceso efectivo e herencia completa; no añadas denegaciones generales sin comprender el efecto.','Review full effective access and inheritance; do not add broad deny entries without understanding their effect.')),
 Q(B('¿Una cuenta nueva con el mismo nombre conserva necesariamente el SID antiguo?','Does a new account with the same name necessarily retain the old SID?'),[B('Sí.','Yes.'),B('No.','No.'),B('Solo si el perfil existe.','Only if the profile exists.')],1,B('Nombre de cuenta e identificador de seguridad son cosas distintas.','Account name and security identifier differ.')),B('Confundir permisos de recurso compartido con toda la autorización NTFS.','Confusing share permissions with complete NTFS authorization.'),B('Verifica con el usuario que debe recibir o perder el acceso.','Verify as the user intended to receive or lose access.'),['ms-acl','ms-profiles'],['M17','M18']),
L('OS-W03',B('PowerShell: objetos y scripts fiables','PowerShell: objects and reliable scripts'),B('¿Por qué exportar una tabla puede destruir tus datos?','Why can exporting a formatted table destroy your data?'),B('Procesar objetos, validar entradas y producir resultados comprobables.','Process objects, validate inputs and produce checkable results.'),[
 C(B('Propiedades antes de formato','Properties before formatting'),B('Entre cmdlets circulan objetos con propiedades y tipos. Get-Member descubre estructura; Where-Object filtra y Select-Object selecciona. Format-Table produce instrucciones de presentación: no lo uses antes de Export-Csv para representar datos. Programas nativos tienen reglas distintas; PowerShell 7.4 añadió preservación de bytes en determinados flujos nativos. Registrar versión sigue siendo obligatorio.','Cmdlets exchange typed objects with properties. Get-Member reveals structure, Where-Object filters and Select-Object selects. Format-Table produces presentation instructions; do not put it before Export-Csv for data output. Native programs have different rules; PowerShell 7.4 added byte preservation for selected native flows. Recording the version remains essential.'),B('Filtra objetos; presenta al final.','Filter objects; format last.')),
 C(B('Errores con contrato','Errors with a contract'),B('try/catch captura errores terminantes. Muchos cmdlets producen errores no terminantes salvo que se solicite ErrorAction Stop. Las aplicaciones nativas requieren interpretar su código según su contrato; LASTEXITCODE y el flujo de errores de PowerShell no son equivalentes. WhatIf solo previsualiza comandos que implementan ese comportamiento y no sustituye un rollback.','try/catch handles terminating errors. Many cmdlets emit nonterminating errors unless ErrorAction Stop is requested. Native application exit codes need their own contract; LASTEXITCODE is not equivalent to PowerShell error streams. WhatIf previews commands implementing that behavior and does not replace rollback.'),B('Un fallo debe ser visible y distinguible de vacío.','Failure must be visible and distinct from empty output.')),
 C(B('Datos y portabilidad','Data and portability'),B('LiteralPath evita interpretar patrones en rutas. JSON necesita profundidad suficiente; CSV pierde parte de la información de tipos y necesita encabezados/codificación acordados. Separa datos de diagnósticos y no exportes todos los campos sin necesidad: inventarios pueden contener datos sensibles. PowerShell portable no implica portabilidad de los cmdlets específicos de Windows.','LiteralPath avoids pattern interpretation in paths. JSON needs sufficient depth; CSV loses some type information and needs agreed headers/encoding. Separate data from diagnostics and do not export unnecessary fields: inventories can contain sensitive data. Portable PowerShell does not make Windows-specific cmdlets portable.'),B('Esquema explícito, salida mínima.','Explicit schema, minimum output.'))],
 [B('Entrada validada','Validated input'),B('Objetos de archivos','File objects'),B('Propiedades elegidas','Selected properties'),B('JSON / CSV verificable','Checkable JSON / CSV')],
 E(B('Inventario de archivos inmediatos','Immediate-file inventory'),'PowerShell',"param([Parameter(Mandatory)][string]$Folder)\n$ErrorActionPreference = 'Stop'\ntry {\n  if (-not (Test-Path -LiteralPath $Folder -PathType Container)) { throw 'Invalid directory' }\n  $items = @(Get-ChildItem -LiteralPath $Folder -File -Force |\n    Where-Object { -not ($_.Attributes -band [IO.FileAttributes]::ReparsePoint) } |\n    Select-Object Name,Length)\n  [pscustomobject]@{Count=$items.Count; Files=$items} | ConvertTo-Json -Depth 4\n} catch { Write-Error -Message $_ -ErrorAction Continue; exit 1 }",B('Un objeto JSON con Count y Files. Una carpeta vacía tiene Count=0, no un error.','One JSON object with Count and Files. An empty directory has Count=0 rather than an error.'),B('Guarda como inventario.ps1 fuera del dataset y ejecútalo conforme a la política de scripts de la VM. No se prescribe Bypass ni desactivar controles.','Save as inventario.ps1 outside the dataset and execute under the VM script policy. No Bypass or control disabling is prescribed.')),
 P(B('PowerShell identificado, carpeta nueva y política que autoriza el script revisado.','Identified PowerShell version, new directory and policy authorizing the reviewed script.'),[
 S(B('Crea un dataset de un archivo y consulta sus propiedades.','Create a one-file dataset and inspect its properties.'),B('Nombre y Length son datos; una tabla visual es otra cosa.','Name and Length are data; a visual table is different.'),'$d=Join-Path $env:TEMP ([guid]::NewGuid()); New-Item -ItemType Directory $d | Out-Null; [IO.File]::WriteAllText((Join-Path $d "a.txt"), "abc"); Get-ChildItem -LiteralPath $d | Get-Member'),
 S(B('Guarda el ejemplo fuera del dataset y ejecútalo con la ruta d.','Save the example outside the dataset and run with path d.'),B('Count=1 y Length=3; no hay modificaciones de entrada.','Count=1 and Length=3; no input modifications.'),'./inventario.ps1 -Folder $d'),
 S(B('Prueba una carpeta vacía y una ruta inexistente como procesos separados.','Test an empty directory and nonexistent path in separate processes.'),B('Vacío válido frente a error con código 1. Anota el motor usado.','Valid emptiness versus an error with status 1. Record the engine used.')),
 S(B('Exporta las propiedades a CSV y reimpórtalas.','Export selected properties to CSV and import them again.'),B('No aparecen objetos FormatStartData; conserva campos y codificación.','No FormatStartData objects; preserve fields and encoding.'),'Get-ChildItem -LiteralPath $d -File | Select-Object Name,Length | Export-Csv -NoTypeInformation -LiteralPath (Join-Path $env:TEMP "os-inventario.csv")')],B('Script revisado, JSON/CSV y casos positivo, vacío e inválido.','Reviewed script, JSON/CSV and positive, empty and invalid cases.'),B('Explicas objetos, errores y formato sin depender de una tabla localizada.','Explain objects, errors and formatting without relying on localized tables.'),B('Retira solo archivos del dataset y salidas propias tras conservar evidencias.','Remove only dataset files and own outputs after preserving evidence.'),B('La política no autoriza el script.','Policy does not authorize the script.'),B('Solicita el procedimiento autorizado del aula o firma prevista; no cambies la política global.','Use the approved classroom process or required signing; do not change global policy.')),
 Q(B('¿Qué debe ir antes de Export-Csv?','What belongs before Export-Csv?'),[B('Format-Table.','Format-Table.'),B('Objetos con propiedades seleccionadas.','Objects with selected properties.'),B('Una captura de pantalla.','A screenshot.')],1,B('Los objetos de formato no son los datos originales.','Formatting objects are not the original data.')),B('Suponer que try/catch captura cualquier error sin revisar su tipo.','Assuming try/catch catches every error without considering its type.'),B('Una salida estructurada necesita errores igualmente definidos.','Structured output needs equally explicit error behavior.'),['powershell','ps-errors'],['M16','M17']),
L('OS-W04',B('CMD y BAT: legado comprensible','CMD and BAT: understandable legacy'),B('¿Por qué un lote funciona distinto de PowerShell?','Why does a batch file behave differently from PowerShell?'),B('Leer un lote pequeño, verificar su resultado y reconocer cuándo migrarlo.','Read a small batch file, verify its output and recognize when to migrate.'),[
 C(B('Intérprete y expansión','Interpreter and expansion'),B('cmd.exe tiene comandos internos y lanza ejecutables. Sus variables usan %VAR%; en bloques, la expansión puede ocurrir antes de la ejecución de sus líneas. La expansión diferida permite otro comportamiento pero afecta a signos de exclamación. BAT no comparte reglas con Bash ni PowerShell. Mantén las extensiones y el alcance del entorno con setlocal/endlocal.','cmd.exe contains internal commands and launches executables. Variables use %VAR%; blocks may expand variables before their lines execute. Delayed expansion changes behavior but affects exclamation marks. BAT does not share Bash or PowerShell rules. Scope environment and extensions with setlocal/endlocal.'),B('La sintaxis pertenece al intérprete.','Syntax belongs to the interpreter.')),
 C(B('Utilidades y estados','Utilities and exit codes'),B('dir lista, type lee texto, fc compara y where.exe localiza ejecutables. sc.exe es el programa de servicios y no debe confundirse con alias de otro shell. Captura errorlevel antes de ejecutar una orden que lo cambie. Algunos programas, como robocopy, tienen códigos documentados donde un valor no cero no significa necesariamente fallo completo.','dir lists, type reads text, fc compares and where.exe locates executables. sc.exe is the service program and must not be confused with another shell alias. Capture errorlevel before another command changes it. Programs such as robocopy document return codes where nonzero does not necessarily mean complete failure.'),B('Cada ejecutable define sus códigos.','Each executable defines its exit codes.')),
 C(B('Elegir la herramienta','Choose the right tool'),B('BAT resulta útil para arrancadores y legado simple. Parsing complejo, Unicode, APIs, secretos y objetos son motivos para preferir PowerShell u otro lenguaje apropiado. El ejercicio usa una carpeta fija junto al script y archivos del alumno, no cadenas arbitrarias recibidas por red. No conviertas el ejemplo en un servicio que ejecuta parámetros remotos.','BAT is useful for launchers and simple legacy tasks. Complex parsing, Unicode, APIs, secrets and objects are reasons to prefer PowerShell or another suitable language. This lab uses a fixed folder next to the script and learner-created files, not arbitrary network strings. Do not turn this example into a remote-argument execution service.'),B('Mantener legado no obliga a ampliarlo.','Maintaining legacy does not require extending it.'))],
 [B('cmd.exe','cmd.exe'),B('Entorno local','Local environment'),B('Archivos conocidos','Known files'),B('Recuento y estado','Count and status')],
 E(B('contar.cmd con alcance explícito','contar.cmd with explicit scope'),'CMD / BAT',"@echo off\nsetlocal EnableExtensions DisableDelayedExpansion\nif not exist \"%~dp0datos\\\" (\n  echo Falta la carpeta datos 1>&2\n  exit /b 2\n)\nset /a count=0\nfor %%F in (\"%~dp0datos\\*\") do if exist \"%%~fF\" if not exist \"%%~fF\\\" set /a count+=1 >nul\necho files=%count%\nexit /b 0",B('Con dos archivos y una subcarpeta en datos, muestra files=2.','With two files and one subfolder in datos, displays files=2.'),B('El ejemplo cuenta archivos visibles inmediatos, sin pretender equivalencia completa con la CLI PowerShell. La carpeta depende de la ubicación del lote, no del directorio actual.','This counts immediate visible files without claiming full equivalence to the PowerShell CLI. The folder is relative to the batch file location, not the current directory.')),
 P(B('Windows, cmd.exe, editor y una carpeta nueva con contar.cmd. No requiere elevación.','Windows, cmd.exe, editor and a new folder containing contar.cmd. No elevation needed.'),[
 S(B('Guarda el lote y crea junto a él datos con dos archivos y una subcarpeta.','Save the batch file and create datos next to it with two files and one subfolder.'),B('Recuento manual de referencia =2.','Manual reference count=2.')),
 S(B('Ejecuta contar.cmd desde CMD y consulta errorlevel inmediatamente.','Run contar.cmd in CMD and immediately inspect errorlevel.'),B('files=2 y estado 0.','files=2 and status 0.'),'contar.cmd\necho %errorlevel%'),
 S(B('Cambia a otro directorio y llama al lote mediante su ruta entrecomillada.','Change working directory and call the batch file by its quoted path.'),B('Mismo resultado gracias a %~dp0.','Same result because of %~dp0.')),
 S(B('Renombra datos a datos-prueba y repite; después restaura el nombre.','Rename datos to datos-prueba and repeat; then restore the name.'),B('Mensaje de error y estado 2; ninguna carpeta ajena se modifica.','Error message and status 2; no unrelated folder changes.'))],B('Lote, árbol de archivos y tres pruebas.','Batch file, directory tree and three tests.'),B('Explicas límites, ruta del script y códigos sin mezclar shells.','Explain scope, script location and exit codes without mixing shells.'),B('Retira solo el lote y datos ficticios del ejercicio.','Remove only the batch file and fictitious exercise data.'),B('Se pega el bucle en PowerShell y falla.','The loop is pasted into PowerShell and fails.'),B('Abre CMD o invoca el archivo .cmd; no traduzcas signos al azar.','Open CMD or invoke the .cmd file; do not randomly translate symbols.')),
 Q(B('¿%~dp0 representa el directorio actual?','Does %~dp0 mean the current directory?'),[B('Sí siempre.','Always.'),B('No; la unidad/ruta del lote.','No; the batch file drive/path.'),B('El perfil del administrador.','The administrator profile.')],1,B('Permite construir una ruta relativa al archivo por lotes.','It supports paths relative to the batch file.')),B('Usar BAT para interpretar entradas externas complejas sin un contrato seguro.','Using BAT to parse complex external input without a safe contract.'),B('Conoce el legado y migra cuando sus límites importan.','Understand legacy and migrate when its limits matter.'),['windows-commands'],['M14','M15']),
L('OS-W05',B('Servicios, tareas y eventos','Services, tasks and events'),B('¿Quién ejecuta la tarea cuando tú no la estás mirando?','Who runs the task when you are not watching?'),B('Relacionar identidad, ejecutable, programación, resultado y registro.','Relate identity, executable, schedule, outcome and log.'),[
 C(B('Servicio, tarea y aplicación','Service, task and application'),B('Un servicio tiene relación con Service Control Manager; una tarea programada tiene desencadenantes, acciones y principal; una aplicación interactiva vive en una sesión. Pueden ejecutar programas similares con entornos distintos. Consulta el objeto antes de detenerlo: nombre conocido no prueba necesidad ni legitimidad. Las dependencias y la cuenta de servicio condicionan el efecto de una modificación.','A service has a Service Control Manager contract; a scheduled task has triggers, actions and a principal; an interactive application lives in a session. They can run similar programs in different environments. Inspect the object before stopping it: a familiar name does not establish necessity or legitimacy. Dependencies and service identity affect changes.'),B('Identidad y entorno forman parte del servicio.','Identity and environment are part of the service.')),
 C(B('Programación revisable','Reviewable scheduling'),B('Programa solo un script que ya funciona de forma manual. Define ruta absoluta, argumentos, directorio, usuario, privilegio mínimo y salida. Una tarea registrada no garantiza ejecución; LastRunTime y LastTaskResult se interpretan junto al efecto funcional y eventos. La política de scripts sigue aplicando: no añadas Bypass para hacer que la tarea pase.','Schedule only a script already working manually. Define absolute path, arguments, directory, user, least privilege and output. Registration does not guarantee execution; interpret LastRunTime and LastTaskResult with functional results and events. Script policy still applies: do not add Bypass just to make a task succeed.'),B('Registrada, ejecutada y verificada son estados distintos.','Registered, executed and verified are different states.')),
 C(B('Eventos con proveedor y tiempo','Events with provider and time'),B('Get-WinEvent consulta eventos nativos. Filtrar por canal, proveedor e intervalo evita exportar registros innecesarios. Un identificador numérico sin proveedor puede inducir errores. Algunos canales y políticas requieren activación previa y permisos de lectura. La ausencia de un registro puede significar falta de cobertura, no ausencia de ejecución.','Get-WinEvent queries native events. Filter by channel, provider and time to avoid unnecessary exports. Numeric IDs without providers can mislead. Some channels and policies require prior enablement and read permission. A missing event may mean missing coverage rather than no execution.'),B('Evento = proveedor + contexto + cobertura.','Event = provider + context + coverage.'))],
 [B('Definición de tarea','Task definition'),B('Principal y acción','Principal and action'),B('Ejecución','Execution'),B('Resultado + archivo + evento','Result + file + event')],
 E(B('Consulta de tarea docente','Inspect the instructor task'),'PowerShell',"Get-ScheduledTask -TaskName 'OS-Classroom-Demo' | Select-Object TaskName,State,Actions,Principal\nGet-ScheduledTaskInfo -TaskName 'OS-Classroom-Demo' | Select-Object LastRunTime,LastTaskResult\nGet-WinEvent -FilterHashtable @{LogName='System'; StartTime=(Get-Date).AddMinutes(-15)} -MaxEvents 20",B('Si el docente no ha creado la tarea, la primera consulta debe informar que falta.','If the instructor has not created the task, the first query must report it missing.'),B('Un error esperado no se oculta con una falsa fila de éxito. El canal System no garantiza contener todos los eventos de tareas: inspecciona también su canal específico si está habilitado.','Do not replace an expected error with a fabricated success row. System does not necessarily contain all task events: inspect the task channel when enabled.')),
 P(B('VM Windows. Docente prepara OS-Classroom-Demo sin sobrescribir tareas existentes, ejecutando un script firmado/revisado en contexto de alumno y sin privilegios altos. Script: escribir Get-Date -Format o en fecha.txt dentro de su carpeta.','Windows VM. Instructor prepares OS-Classroom-Demo without overwriting existing tasks, running a signed/reviewed script as the learner without highest privileges. Script writes Get-Date -Format o to fecha.txt in its own directory.'),[
 S(B('Ejecuta manualmente el script docente y revisa su ruta de salida.','Run the instructor script manually and inspect its output path.'),B('Solo crea fecha.txt en la carpeta acordada.','Only creates fecha.txt in the agreed folder.')),
 S(B('Compara GUI del Programador de tareas con el ejemplo de consulta.','Compare Task Scheduler GUI with the inspection example.'),B('Coinciden ejecutable, argumentos y principal.','Executable, arguments and principal match.')),
 S(B('Inicia únicamente la tarea de aula autorizada y comprueba hora, resultado y archivo.','Start only the authorized classroom task and check time, result and file.'),B('No basta State=Ready; fecha.txt debe haberse actualizado.','State=Ready is not sufficient; fecha.txt must update.'),'Start-ScheduledTask -TaskName "OS-Classroom-Demo"'),
 S(B('En la copia de ensayo introduce una ruta de salida inexistente y observa el fallo; restaura después.','On the test copy, introduce a nonexistent output path and observe failure; then restore.'),B('El fallo es visible y se diferencia del funcionamiento normal.','Failure is visible and distinct from normal operation.'))],B('Definición, resultado, archivo y cobertura de eventos.','Definition, outcome, file and event coverage.'),B('Demuestras qué identidad ejecuta y cómo sabes que funcionó.','Demonstrate which identity runs the task and how success is known.'),B('Con aprobación docente, desregistra solo OS-Classroom-Demo y retira su archivo; no elimines logs.','With instructor approval, unregister only OS-Classroom-Demo and remove its output; do not delete logs.'),B('A mano funciona y como tarea no encuentra un archivo.','Manual execution works but the task cannot find a file.'),B('Revisa directorio, principal, permisos y variables del contexto no interactivo.','Review directory, principal, permissions and noninteractive environment.')),
 Q(B('¿State=Ready demuestra que el trabajo terminó bien?','Does State=Ready prove successful work?'),[B('No; comprueba resultado y efecto.','No; check result and effect.'),B('Sí.','Yes.'),B('Solo sin GUI.','Only without GUI.')],0,B('Disponibilidad para ejecutar no prueba una ejecución útil.','Readiness does not prove useful execution.')),B('Detener servicios o borrar tareas por su nombre sin revisar dependencias.','Stopping services or deleting tasks by name without inspecting dependencies.'),B('Una tarea administrable deja una evidencia interpretable.','An administrable task leaves interpretable evidence.'),['ms-tasks','ms-events'],['M17','M19']),
L('OS-W06',B('Directorio, GPO y recursos empresariales','Directory, GPO and enterprise resources'),B('¿Crear el usuario en AD concede acceso a todas las carpetas?','Does creating an AD user grant access to every share?'),B('Distinguir dominio, OU, grupo, política y autorización del recurso.','Distinguish domain, OU, group, policy and resource authorization.'),[
 C(B('AD DS no es solamente LDAP','AD DS is not just LDAP'),B('LDAP permite acceder a un directorio. AD DS integra objetos, dominios, replicación y servicios dependientes de DNS y autenticación. Kerberos depende también de tiempo y nombres. Entra ID es un servicio de identidad distinto; no equivale a un controlador de dominio LDAP universal. Antes de una prueba registra bosque/dominio y OU ficticia autorizada; no enumeres directorios externos al laboratorio.','LDAP provides directory access. AD DS integrates objects, domains, replication and services depending on DNS and authentication. Kerberos also depends on time and names. Entra ID is a different identity service, not a universal LDAP domain controller. Before testing, record the authorized fictitious domain and OU; do not enumerate directories outside the lab.'),B('Directorio, autenticación y autorización cooperan.','Directory, authentication and authorization cooperate.')),
 C(B('Organizar no es autorizar','Organizing is not authorizing'),B('Una OU organiza objetos y ámbito de administración/políticas; un grupo puede conceder acceso; una GPO aplica configuraciones conforme a vínculo, filtrado y precedencia. Ninguno garantiza por su mera existencia el acceso efectivo a una carpeta. En un mover hay que retirar permisos previos injustificados y comprobar la sesión/token actualizado. No acumules privilegios por cada puesto ocupado.','An OU organizes objects and administration/policy scope; a group can grant access; a GPO applies settings through links, filtering and precedence. None alone guarantees effective folder access. A mover requires removal of unjustified old access and verification of the updated session/token. Do not accumulate privileges from every previous role.'),B('OU ≠ grupo ≠ GPO.','OU ≠ group ≠ GPO.')),
 C(B('Canales y recursos compartidos','Channels and shares'),B('LDAP signing, TLS y channel binding no son nombres de un mismo control. El valor predeterminado depende de versión y si el entorno es nuevo o actualizado. Para SMB se revisan permisos del share y NTFS, además de firma/cifrado y conectividad. Las credenciales administrativas y de recuperación no se exportan al cuaderno.','LDAP signing, TLS and channel binding are not the same control. Defaults depend on version and whether deployment is new or upgraded. For SMB, inspect both share and NTFS permissions alongside signing/encryption and connectivity. Administrative and recovery credentials never belong in the notebook.'),B('Conexión segura y permiso correcto son pruebas diferentes.','Secure connection and correct access are different checks.'))],
 [B('Usuario en OU de aula','User in lab OU'),B('Grupo de función','Role group'),B('GPO y contexto','GPO and context'),B('Share + ACL efectiva','Share + effective ACL')],
 E(B('Consultas acotadas al usuario de práctica','Queries scoped to the lab user'),'PowerShell · RSAT AD',"Get-ADUser -Identity 'os.reader' -Properties Enabled,MemberOf | Select-Object SamAccountName,Enabled,MemberOf\nGet-ADGroupMember -Identity 'OS-Lab-Readers' | Select-Object SamAccountName,ObjectClass\ngpresult.exe /r /scope user",B('Identidad y pertenencias esperadas del laboratorio; no inventar objetos si faltan.','Expected lab identity and memberships; do not invent results when objects are absent.'),B('Requiere dominio aislado, herramientas AD y permisos de consulta. La consulta no cambia usuarios. En un equipo sin AD la ejecución nativa queda pendiente.','Requires an isolated domain, AD tools and read permission. Queries change no users. Native execution remains pending on a device without AD.')),
 P(B('Dominio aislado y cuentas os.reader/os.editor, grupos OS-Lab-Readers/Editors, OU de aula y recurso compartido preparado. Cambios aprobados por el docente.','Isolated domain with os.reader/os.editor, OS-Lab-Readers/Editors groups, lab OU and a prepared share. Instructor-approved changes only.'),[
 S(B('Dibuja objetos, DNS, autenticación y recurso. Ejecuta consultas exactas del ejemplo.','Draw objects, DNS, authentication and resource. Run the exact example queries.'),B('No se usan comodines para listar todo el dominio.','No wildcards enumerate the whole domain.')),
 S(B('Compara política esperada y gpresult del usuario; registra una configuración aplicada.','Compare expected policy with user gpresult; record one applied setting.'),B('Vínculo de GPO no se confunde con resultado efectivo.','A GPO link is not confused with effective results.')),
 S(B('Prueba lectura, modificación y cambio de permisos desde cada cuenta de aula.','Test reading, modifying and changing permissions under each lab account.'),B('El lector lee pero no modifica; editor modifica datos pero no administra ACL según diseño.','Reader reads without modifying; editor changes data but not ACLs as designed.')),
 S(B('Planifica mover editor a lector y después leaver; el docente ejecuta cambios y renueva la sesión para retest.','Plan an editor-to-reader move and then offboarding; instructor applies changes and refreshes the session for retesting.'),B('Registra acceso nuevo y sesiones antiguas por separado.','Record new access and old sessions separately.'))],B('Diagrama, consultas acotadas, política resultante y matriz JML.','Diagram, scoped queries, resulting policy and JML matrix.'),B('Puedes explicar por qué existe un usuario pero no tiene cierto permiso.','Explain why a user exists but lacks a particular permission.'),B('Retira solo cambios de la OU/grupos de práctica según plan; conserva acceso de recuperación.','Remove only planned lab OU/group changes and preserve recovery access.'),B('La GPO no llega al usuario esperado.','The GPO does not reach the intended user.'),B('Revisa vínculo, ámbito, filtros, conectividad y resultado, no desactives GPO globales.','Review links, scope, filters, connectivity and results; do not disable global GPOs.')),
 Q(B('¿Una OU concede por sí sola permiso de escritura a un share?','Does an OU by itself grant write access to a share?'),[B('Sí.','Yes.'),B('No.','No.'),B('Solo con DNS.','Only with DNS.')],1,B('Organización y autorización del recurso son conceptos diferentes.','Organization and resource authorization are different concepts.')),B('Mezclar un directorio real con prácticas sin alcance documentado.','Mixing a live directory with labs lacking documented scope.'),B('Cada concesión necesita dueño, alcance y prueba de revocación.','Every grant needs an owner, scope and revocation test.'),['ms-ad','ms-ldap','ms-smb'],['M18']),
L('OS-W07',B('Red, acceso remoto y navegación','Networking, remote access and browsing'),B('¿Bloquear un dominio distingue una cuenta personal de una corporativa?','Does blocking a domain distinguish personal and corporate accounts?'),B('Relacionar configuración del host, reglas y contexto de identidad.','Relate host configuration, rules and identity context.'),[
 C(B('Diagnóstico por evidencia','Evidence-driven diagnosis'),B('Get-NetIPConfiguration identifica interfaces; Get-NetRoute rutas; Resolve-DnsName consulta nombres; Get-NetTCPConnection sockets; Test-NetConnection prueba un destino explícito. La prueba produce tráfico: limita destino y puerto. RDP, WinRM y SSH requieren configuración y edición adecuadas, confianza y autorización. No expongas estos servicios a Internet para simplificar una clase.','Get-NetIPConfiguration identifies interfaces; Get-NetRoute routes; Resolve-DnsName names; Get-NetTCPConnection sockets; Test-NetConnection tests an explicit target. Testing creates traffic: restrict target and port. RDP, WinRM and SSH need suitable configuration/edition, trust and authorization. Do not expose them publicly to simplify a class.'),B('Un puerto abierto no prueba autorización.','An open port does not prove authorization.')),
 C(B('Perfiles y puntos de control','Profiles and enforcement points'),B('Windows Firewall aplica reglas asociadas a perfiles y condiciones. Una regla creada puede no cubrir la interfaz o perfil efectivo. Proxy del usuario, WinHTTP, navegador y agente de seguridad no son necesariamente la misma configuración. Inventaría qué tráfico llega al punto de control antes de concluir que una categoría está bloqueada para todos los programas.','Windows Firewall applies rules to profiles and conditions. A created rule may not cover the effective interface/profile. User proxy, WinHTTP, browser and security agent settings are not necessarily identical. Inventory traffic reaching each enforcement point before claiming a category is blocked for every application.'),B('Configurado no significa aplicado a ese flujo.','Configured does not mean applied to that flow.')),
 C(B('Cuenta, aplicación y cifrado','Account, application and encryption'),B('Correo personal y corporativo pueden compartir destinos: separar cuentas puede exigir políticas de tenant, navegador o SaaS compatibles. La inspección TLS no elimina el cifrado E2EE de los mensajes. Prueba solo datos sintéticos y equipos administrados autorizados; no instales CA de inspección en dispositivos personales. Define excepciones, retención y recuperación antes de bloquear.','Personal and corporate mail may share destinations: account separation may require compatible tenant, browser or SaaS policy. TLS inspection does not remove message E2EE. Use synthetic data and authorized managed devices only; do not install inspection CAs on personal devices. Define exceptions, retention and recovery before blocking.'),B('Control de destino ≠ control de cuenta ≠ lectura de contenido.','Destination control ≠ account control ≠ content access.'))],
 [B('Sujeto y dispositivo','Subject and device'),B('Ruta y perfil','Route and profile'),B('Regla del control','Enforcement rule'),B('Permitir / denegar / no cubierto','Allow / deny / uncovered')],
 E(B('Observar antes de crear reglas','Observe before creating rules'),'PowerShell',"Get-NetIPConfiguration\nGet-NetConnectionProfile\nGet-NetFirewallProfile | Select-Object Name,Enabled,DefaultInboundAction,DefaultOutboundAction\nGet-NetTCPConnection -State Listen | Select-Object LocalAddress,LocalPort,OwningProcess\nnetsh.exe winhttp show proxy",B('Configuración observada del equipo propio. Los resultados dependen de política y permisos.','Observed configuration of your device. Results depend on policy and permissions.'),B('No altera reglas. WinHTTP no representa automáticamente la configuración de todos los navegadores y aplicaciones.','Changes no rules. WinHTTP does not automatically represent every browser/application configuration.')),
 P(B('VM Windows, servidor de aula y política de ejemplo aprobada. No tráfico ni cuentas personales.','Windows VM, classroom server and approved example policy. No personal traffic/accounts.'),[
 S(B('Ejecuta consultas y relaciona listener/proceso/perfil.','Run queries and relate listener/process/profile.'),B('Lista mínima con propósito de cada flujo.','Minimum list describing each flow purpose.')),
 S(B('Comprueba un único puerto aprobado del servidor de aula con Test-NetConnection.','Use Test-NetConnection for one approved classroom server port.'),B('Resultado de transporte, no de toda la aplicación.','Transport result, not complete application health.')),
 S(B('Diseña tres reglas sintéticas: correo de tenant permitido, cuenta personal denegada y dispositivo invitado fuera de alcance.','Design three synthetic rules: allowed mail tenant, denied personal account and guest device out of scope.'),B('Cada regla identifica el punto capaz de distinguir esos atributos.','Each rule names an enforcement point able to distinguish the attributes.')),
 S(B('Valida una excepción temporal en la tabla y redacta cómo verificar y revocar su efecto.','Validate a temporary exception in the table and describe effective checking and revocation.'),B('La tabla se etiqueta como diseño, no como política instalada.','Label the table as design, not installed policy.'))],B('Mapa, pruebas de transporte y tabla de política con cobertura.','Map, transport checks and policy table with coverage.'),B('Explicas qué controla cada mecanismo y qué queda fuera.','Explain each mechanism scope and what remains uncovered.'),B('Revoca accesos de prueba según el docente; no se cambian políticas del host personal.','Revoke test access as instructed; personal host policies remain unchanged.'),B('El navegador funciona pero una aplicación nativa no usa el proxy previsto.','The browser works but a native app does not use the intended proxy.'),B('Comprueba configuración y encaminamiento de esa aplicación; no declares cobertura universal.','Check that application configuration/routing; do not claim universal coverage.')),
 Q(B('¿Un filtro DNS distingue siempre tenants de un mismo proveedor?','Does DNS filtering always distinguish one provider tenants?'),[B('Sí.','Yes.'),B('No; pueden compartir dominios.','No; they may share domains.'),B('Solo en Windows.','Only on Windows.')],1,B('La decisión requiere atributos disponibles en el punto de control.','The decision requires attributes available to the enforcement point.')),B('Desactivar firewall o validación TLS para hacer pasar una prueba.','Disabling firewall or TLS validation to make a test pass.'),B('Define la cobertura antes de medir el bloqueo.','Define coverage before measuring blocking.'),['ms-network','ms-tenant','openssh'],['M18','M24']),
L('OS-W08',B('Bastionado, detección y recuperación Windows','Windows hardening, detection and recovery'),B('¿Un equipo sin alertas está realmente protegido?','Is an alert-free device actually protected?'),B('Revisar controles y correlacionar una acción benigna con evidencia.','Review controls and correlate a benign action with evidence.'),[
 C(B('Baseline con recuperación','Baseline with recovery'),B('Revisa soporte y parches, cuentas, NTFS, servicios, firewall, protección de endpoint, auditoría y copias. BitLocker protege volúmenes según configuración y estado; recuperabilidad exige custodiar protectores sin publicarlos. LAPS gestiona contraseñas administrativas locales en escenarios compatibles, no reemplaza todos los permisos. No alteres cifrado o acceso remoto sin una vía de recuperación.','Review support/patches, accounts, NTFS, services, firewall, endpoint protection, auditing and backups. BitLocker protects volumes according to configuration/state; recovery requires safeguarded protectors without publishing them. LAPS manages local administrator passwords in supported scenarios, not all authorization. Do not change encryption or remote access without recovery.'),B('Proteger incluye poder recuperar.','Protection includes recoverability.')),
 C(B('Fuentes de detección','Detection sources'),B('Defender, Windows Event Log, PowerShell logging y Sysmon ofrecen fuentes distintas. Sysmon depende de su configuración; instalarlo no captura automáticamente todo. Un evento de grupo administrativo necesita proveedor, sujeto, objeto y hora, y debe compararse con un cambio aprobado. Un agente sin reportar es pérdida de visibilidad, no cero amenazas.','Defender, Windows Event Log, PowerShell logging and Sysmon provide different sources. Sysmon depends on configuration; installation does not capture everything automatically. An administrator-group event needs provider, subject, object and time and must be compared with approved changes. A nonreporting agent means lost visibility, not zero threats.'),B('Detectar también la ausencia de telemetría.','Detect missing telemetry too.')),
 C(B('Triage sin sobreafirmar','Triage without overclaiming'),B('Preserva el estado, acota la pregunta y recoge evidencia proporcional. Un nombre de proceso o coincidencia de indicador no acredita compromiso. Una intervención puede generar eventos y modificar el sistema: registra ese impacto. La contención debe estar autorizada, tener objetivo y permitir verificar disponibilidad y restauración. No se ejecuta malware en esta práctica.','Preserve state, scope the question and gather proportionate evidence. A process name or indicator match does not establish compromise. An intervention can generate events and modify the system: record the impact. Containment needs authorization, purpose and availability/restore checks. This lab executes no malware.'),B('Hechos y límites antes de atribuir un incidente.','Facts and limits before attributing an incident.'))],
 [B('Control configurado','Configured control'),B('Acción benigna','Benign action'),B('Evento corroborado','Corroborated event'),B('Recuperación comprobada','Checked recovery')],
 E(B('Estado de protección y eventos acotados','Protection state and scoped events'),'PowerShell',"Get-MpComputerStatus | Select-Object AntivirusEnabled,RealTimeProtectionEnabled,AntivirusSignatureLastUpdated\nGet-WinEvent -FilterHashtable @{LogName='System'; StartTime=(Get-Date).AddMinutes(-30)} -MaxEvents 10 |\n  Select-Object TimeCreated,ProviderName,Id,LevelDisplayName",B('Estado y eventos si las capacidades están disponibles. Cmdlet ausente o acceso denegado se registra como no evaluado.','State and events when available. A missing cmdlet or denied access is recorded as unassessed.'),B('No extrae claves, contraseñas ni contenido de usuario. La observación no acredita todos los controles de una baseline.','Extracts no keys, passwords or user content. This observation does not establish every baseline control.')),
 P(B('VM Windows protegida, dataset propio con copia y tarea benigna de OS-W05. Cambios de control solo aprobados por el docente.','Protected Windows VM, own backed-up dataset and OS-W05 benign task. Only instructor-approved control changes.'),[
 S(B('Registra diez controles y diferencia verificado, configurado y no evaluado.','Record ten controls and distinguish verified, configured and unassessed.'),B('No exportes protectores BitLocker ni secretos LAPS.','Do not export BitLocker protectors or LAPS secrets.')),
 S(B('Ejecuta la tarea benigna y busca evidencia por proveedor y ventana.','Run the benign task and look for evidence by provider and window.'),B('Corrobora con su resultado funcional.','Corroborate with its functional result.')),
 S(B('Introduce un error de permiso solo en una copia ficticia y aplica la corrección mínima con rollback.','Introduce a permission error only in a fictitious copy and apply a minimal reversible fix.'),B('El uso legítimo se recupera y la restricción prevista permanece.','Legitimate use recovers while the intended restriction remains.')),
 S(B('Restaura un documento en ruta distinta y defiende un informe de una página.','Restore a document to a separate path and defend a one-page report.'),B('Contenido y permisos comprobados, hipótesis y límites explícitos.','Contents and permissions checked; hypotheses and limitations explicit.'))],B('Baseline, extractos minimizados, ticket y restauración.','Baseline, minimized excerpts, change record and restore.'),B('Puedes operar, proteger e investigar sin apagar los controles de seguridad.','Operate, protect and investigate without switching off security controls.'),B('Retira tareas y accesos de ensayo con aprobación; conserva registros.','Remove test tasks and grants with approval; preserve records.'),B('La búsqueda no devuelve el evento esperado.','The query returns no expected event.'),B('Comprueba auditoría, proveedor, canal, hora, permisos y retención antes de concluir ausencia de actividad.','Check auditing, provider, channel, time, permissions and retention before concluding no activity.')),
 Q(B('¿Un agente offline equivale a un endpoint sin amenazas?','Does an offline agent mean a threat-free endpoint?'),[B('Sí.','Yes.'),B('No; falta visibilidad.','No; visibility is missing.'),B('Solo si no hubo alertas.','Only if there were no alerts.')],1,B('El estado del sensor es parte de la cobertura.','Sensor state is part of coverage.')),B('Recoger perfiles completos o secretos para un informe de estado sencillo.','Collecting full profiles or secrets for a simple status report.'),B('Una defensa útil conserva operación y evidencia.','Useful defense preserves operation and evidence.'),['ms-defender','ms-events','ms-bitlocker','nist-ir'],['M19','M28','M30'])
]
